#include <stdio.h>

int main() {
    int a[] = {4, 7, 4, 2, 7, 9, 2};
    int n = 7;
    int unique[7];
    int count = 0;
    for (int i = 0; i < n; i++) {
        int seen = 0;
        for (int j = 0; j < count; j++) {
            if (unique[j] == a[i]) {
                seen = 1;
                break;
            }
        }
        if (!seen) {
            unique[count++] = a[i];
        }
    }
    for (int i = 0; i < count; i++) printf("%d ", unique[i]);
    printf("\n");
    return 0;
}
